pub fn vec_len<T>(x: &Vec<T>) -> usize {
    x.len()
}

pub fn numpy_log10(x: Vec<f32>) -> Vec<f32> {
    let n = x.len(); // assumed > 0 by the problem statement
    let mut result: Vec<f32> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n {
        // i is always in-bounds here
        result.push(x[i]);
        i += 1;
    }

    // Ensure the returned vector has exactly the same length as the input.
    debug_assert_eq!(result.len(), n);

    result
}